CREATE TABLE IF NOT EXISTS cafe_settings (id serial PRIMARY KEY, cafe_name varchar(160) NOT NULL DEFAULT 'Sukoon Cafe', tagline varchar(240) NOT NULL DEFAULT 'A little pause. A little sukoon.', address text NOT NULL DEFAULT 'Ashiyana Road, LDA Colony, Lucknow', phone varchar(40), email varchar(255), opening_hours text, currency varchar(3) NOT NULL DEFAULT 'INR', tax_rate_bps integer NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
